const data = $('Normalize Supplier Data').first().json;

const mandatoryCriteriaPassed =
  data.taxRegistrationAvailable === 'Yes' &&
  data.requiredDocumentsAvailable !== 'Not Available';

let mandatoryFailureReason = '';

if (data.taxRegistrationAvailable !== 'Yes') {
  mandatoryFailureReason = 'Valid tax registration is required.';
} else if (data.requiredDocumentsAvailable === 'Not Available') {
  mandatoryFailureReason = 'Mandatory supplier documents are not available.';
}

return [
  {
    json: {
      ...data,
      mandatoryCriteriaPassed,
      mandatoryFailureReason,
    },
  },
];

const data = $input.first().json;

const qualityScores = {
  'Certified Quality Management System': 100,
  'Documented Quality Procedures': 75,
  'Basic Quality Controls': 50,
  'No Formal Quality System': 20,
};

const deliveryScores = {
  'Proven On-Time Delivery Above 95%': 100,
  'Consistent Delivery 85% to 95%': 80,
  'Moderate Delivery 70% to 84%': 60,
  'Limited or Unproven Delivery Capability': 30,
};

const commercialScores = {
  'Highly Competitive': 100,
  'Competitive': 80,
  'Acceptable': 60,
  'Above Market': 30,
};

const capacityScores = {
  'Exceeds Expected Demand': 100,
  'Meets Expected Demand': 80,
  'Limited Capacity Headroom': 60,
  'Insufficient or Unverified Capacity': 30,
};

const complianceScores = {
  'Fully Compliant': 100,
  'Minor Compliance Gaps': 70,
  'Major Compliance Gaps': 40,
  'Non-Compliant': 0,
};

const qualityScore = qualityScores[data.qualityCapability] ?? 0;
const deliveryScore = deliveryScores[data.deliveryCapability] ?? 0;
const commercialScore = commercialScores[data.commercialCompetitiveness] ?? 0;
const capacityScore = capacityScores[data.capacityLevel] ?? 0;
const complianceScore = complianceScores[data.complianceStatus] ?? 0;

// Experience scoring
let experienceScore = 40;

if (data.yearsInBusiness >= 10) {
  experienceScore = 100;
} else if (data.yearsInBusiness >= 5) {
  experienceScore = 80;
} else if (data.yearsInBusiness >= 2) {
  experienceScore = 60;
}

// Capacity carries 70%, experience carries 30%
const capacityExperienceScore = Math.round(
  (capacityScore * 0.70) + (experienceScore * 0.30)
);

return [
  {
    json: {
      ...data,
      qualityScore,
      deliveryScore,
      commercialScore,
      capacityScore,
      experienceScore,
      capacityExperienceScore,
      complianceScore,
    },
  },
];

const data = $input.first().json;

const weightedScore =
  (data.qualityScore * data.qualityWeight) +
  (data.deliveryScore * data.deliveryWeight) +
  (data.commercialScore * data.commercialWeight) +
  (data.capacityExperienceScore * data.capacityWeight) +
  (data.complianceScore * data.complianceWeight);

const finalWeightedScore = Math.round(weightedScore * 10) / 10;

return [
  {
    json: {
      ...data,
      weightedScore: finalWeightedScore,
    },
  },
];

const data = $input.first().json;

let riskLevel = 'Low';
let criticalRiskFlag = false;
let manualReviewRequired = false;
let riskReason = '';

if (
  data.complianceStatus === 'Non-Compliant' &&
  data.criticalRiskOnNonCompliance === true
) {
  riskLevel = 'Critical';
  criticalRiskFlag = true;
  manualReviewRequired = true;
  riskReason = 'Supplier is currently non-compliant with mandatory compliance requirements.';
}
else if (
  data.complianceStatus === 'Major Compliance Gaps' &&
  data.manualReviewOnMajorComplianceGap === true
) {
  riskLevel = 'High';
  manualReviewRequired = true;
  riskReason = 'Major compliance gaps require manual procurement or QA review.';
}
else if (
  data.requiredDocumentsAvailable === 'Partial' ||
  data.bankDetailsAvailable === 'No'
) {
  riskLevel = 'Medium';
  riskReason = 'Supplier has incomplete supporting information requiring follow-up.';
}

return [
  {
    json: {
      ...data,
      riskLevel,
      criticalRiskFlag,
      manualReviewRequired,
      riskReason,
    },
  },
];

const data = $input.first().json;

let qualificationDecision = '';
let supplierStatus = '';
let decisionReason = '';
let reviewRequired = false;

if (data.manualReviewRequired === true) {
  qualificationDecision = 'Manual Review';
  supplierStatus = 'Manual Review';
  decisionReason = data.riskReason || 'Supplier requires manual review.';
  reviewRequired = true;
}
else if (
  data.weightedScore >= data.approvalThreshold &&
  data.riskLevel === 'Low'
) {
  qualificationDecision = 'Approved';
  supplierStatus = 'Approved';
  decisionReason =
    `Supplier achieved a weighted score of ${data.weightedScore} and passed all qualification and risk checks.`;
}
else if (
  data.weightedScore >= data.conditionalThreshold
) {
  qualificationDecision = 'Conditionally Approved';
  supplierStatus = 'Conditionally Approved';

  decisionReason = data.riskReason
    ? `Supplier achieved a weighted score of ${data.weightedScore}, but follow-up is required: ${data.riskReason}`
    : `Supplier achieved a weighted score of ${data.weightedScore}, which meets the conditional approval threshold.`;

  reviewRequired = true;
}
else {
  qualificationDecision = 'Rejected';
  supplierStatus = 'Rejected';
  decisionReason =
    `Supplier weighted score of ${data.weightedScore} is below the minimum qualification threshold of ${data.conditionalThreshold}.`;
}

return [
  {
    json: {
      ...data,
      qualificationDecision,
      supplierStatus,
      decisionReason,
      reviewRequired,
      evaluationStatus: 'Completed',
      decisionAt: new Date().toISOString(),
    },
  },
];
